113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
117	        prepareNewOwner(ownerFieldsDto, registrationDate);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setRegistrationDate(registrationDate);
121	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
122	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
123	        assignHousehold(owner, ownerFieldsDto);
124	        this.clinicService.saveOwner(owner);
125	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
126	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
127	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
128	            ownerMapper.membershipLevel(owner));
129	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
130	        ownerDto.setBulkSignupWarning(bulkSignupWarning(registrationDate));
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
