185	    @Override
186	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner != null) {
189	            Pet currentPet = this.clinicService.findPetById(petId);
190	            if (currentPet != null) {
191	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
192	                currentPet.setName(petFieldsDto.getName());
