215	
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner != null) {
222	            Pet pet = owner.getPet(petId);
223	            if (pet != null) {
224	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
225	            }
226	        }
227	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	    }
229	
230	    /**
231	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
232	     * The address is normalized in place (so a required-field check that follows rejects an
233	     * address blank after normalization), the required fields are checked, the telephone and
234	     * email are normalized in place, and the resulting owner is rejected when its derived
235	     * identity key already belongs to another owner. Each rule
236	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
237	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
238	     * to be mapped and saved.
239	     *
240	     * @param ownerFieldsDto the submitted owner fields, normalized in place
241	     */
242	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
243	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
244	        validateRequiredFields(ownerFieldsDto);
245	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
246	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
247	        rejectDuplicateIdentity(ownerFieldsDto);
248	        rejectCityAtCapacity(ownerFieldsDto.getCity());
249	        rejectDailyLimitExceeded(registrationDate);
250	    }
251	
252	    /**
253	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
254	     * falls on a business day. The date supplied on the request is used when present, otherwise the
255	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
256	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
257	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
258	     * membership number's year segment, the per-day create limit) is computed against.
259	     *
260	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
261	     * @return the effective registration date rolled forward to the next business day
262	     */
263	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
264	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
265	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
266	        return toBusinessDay(effective);
267	    }
268	
269	    /**
270	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
271	     * following Monday, while a weekday is returned unchanged.
272	     *
273	     * @param date the date to adjust
274	     * @return the same date when it is a weekday, otherwise the next Monday
275	     */
276	    private LocalDate toBusinessDay(LocalDate date) {
277	        java.time.DayOfWeek day = date.getDayOfWeek();
278	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
279	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
280	        }
281	        return date;
282	    }
283	
284	    /**
285	     * The maximum number of owners that may be created on a single day. Once this many owners
286	     * already carry today's {@code registrationDate}, no further owner may be created today.
287	     */
288	    private static final long DAILY_OWNER_LIMIT = 100L;
289	
290	    /**
291	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
292	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
293	     * date the new owner would be stored with, so owners are capped per business day. When the limit
294	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
295	     * advice renders as a 429 Too Many Requests response.
296	     *
297	     * @param registrationDate the adjusted business-day registration date of the owner being created
298	     */
299	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
300	        long count = this.clinicService.findAllOwners().stream()
301	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
302	            .count();
303	        if (count >= DAILY_OWNER_LIMIT) {
304	            throw new DailyOwnerLimitExceededException(registrationDate);
305	        }
306	    }
307	
308	    /**
309	     * The number of owners that may carry a single day's {@code registrationDate} before that day
310	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
311	     * the create and read responses report {@code bulkSignupWarning} true for that date.
312	     */
313	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
314	
315	    /**
316	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
317	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
318	     * count is taken against the same adjusted date owners are stored with, mirroring the
319	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
320	     *
321	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
322	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
323	     */
324	    private boolean bulkSignupWarning(LocalDate registrationDate) {
325	        if (registrationDate == null) {
326	            return false;
327	        }
328	        long count = this.clinicService.findAllOwners().stream()
329	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
330	            .count();
331	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
332	    }
333	
334	    /**
335	     * The maximum number of owners a single city may hold. Once a city already contains this
336	     * many owners, no further owner may be created in it.
337	     */
338	    private static final long CITY_OWNER_CAPACITY = 50L;
339	
340	    /**
341	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
342	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
343	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
344	     * which the exception advice renders as a 409 Conflict response.
345	     *
346	     * @param city the city of the owner being created
347	     */
348	    private void rejectCityAtCapacity(String city) {
349	        long count = this.clinicService.findAllOwners().stream()
350	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
351	            .count();
352	        if (count >= CITY_OWNER_CAPACITY) {
353	            throw new CityCapacityExceededException(city);
354	        }
355	    }
356	
357	    /**
358	     * Builds the customer code assigned to a newly created owner. The code is formatted as
359	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
360	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
361	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
362	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
363	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
364	     *
365	     * @param city the owner's city
366	     * @param lastName the owner's last name
367	     * @return the formatted customer code
368	     */
369	    private String nextCustomerCode(String city, String lastName) {
370	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
371	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
372	        long sequence = this.clinicService.findAllOwners().stream()
373	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
374	            .count() + 1L;
375	        return String.format("%s-%s-%04d", city3, last3, sequence);
376	    }
377	
378	    /**
379	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
380	     * with the owner being created, compared case-insensitively. The count is taken before the
381	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
382	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
383	     *
384	     * @param firstName the first name of the owner being created
385	     * @param lastName the last name of the owner being created
386	     * @return the number of pre-existing owners sharing the same first and last name
387	     */
388	    private int countNamesakes(String firstName, String lastName) {
389	        return (int) this.clinicService.findAllOwners().stream()
390	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
391	                && lastName.equalsIgnoreCase(existing.getLastName()))
392	            .count();
393	    }
394	
395	    /**
396	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
397	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
398	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
399	     * the names of every offending field, which the exception advice renders as a 400 response
400	     * with an {@code errors} array.
401	     *
402	     * @param ownerFieldsDto the submitted owner fields
403	     */
404	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
405	        List<String> missing = new ArrayList<>();
406	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
407	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
408	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
409	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
410	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
411	        if (!missing.isEmpty()) {
412	            throw new RequiredFieldsMissingException(missing);
413	        }
414	    }
415	
416	    private void addIfBlank(List<String> missing, String fieldName, String value) {
417	        if (value == null || value.isBlank()) {
418	            missing.add(fieldName);
419	        }
420	    }
421	
422	    /**
423	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
424	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
425	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
426	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
427	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
428	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
429	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
430	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
431	     *
432	     * @param telephone the submitted telephone value
433	     * @return the normalized E.164 telephone
434	     */
435	    private String normalizeTelephone(String telephone) {
436	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
437	        String e164;
438	        if (cleaned.startsWith("+")) {
439	            e164 = "+" + cleaned.substring(1);
440	        } else {
441	            String national = cleaned;
442	            if (national.startsWith("0")) {
443	                national = national.substring(1);
444	            }
445	            e164 = "+61" + national;
446	        }
447	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
448	            throw new InvalidFieldsException(List.of("telephone"));
449	        }
450	        validateNationalNumberLength(e164);
451	        return e164;
452	    }
453	
454	    /**
455	     * The required national-number length (the digits after the country code) for each country
456	     * code we recognize: {@code '+61'} (Australia) requires 9 national digits and {@code '+1'}
457	     * (NANP) requires 10. Keyed by the country-code digits without the leading {@code '+'}.
458	     */
459	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
460	        java.util.Map.of("61", 9, "1", 10);
461	
462	    /**
463	     * Validates the national-number length of an already syntactically valid E.164 telephone
464	     * against its country code. For each recognized country code the digits following the code
465	     * must have exactly the expected length ({@code '+61'} => 9 national digits, {@code '+1'} =>
466	     * 10). When the country code is recognized but the national number is the wrong length an
467	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
468	     * response naming the {@code telephone} field. A country code that is not recognized carries
469	     * no per-country length rule and is left to the general 8-to-15-digit E.164 check.
470	     *
471	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
472	     */
473	    private void validateNationalNumberLength(String e164) {
474	        String digits = e164.substring(1);
475	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
476	            .filter(entry -> digits.startsWith(entry.getKey()))
477	            // longest matching country code wins, so a shorter code cannot shadow a longer one
478	            .max(java.util.Comparator.comparingInt(entry -> entry.getKey().length()))
479	            .ifPresent(entry -> {
480	                int nationalLength = digits.length() - entry.getKey().length();
481	                if (nationalLength != entry.getValue()) {
482	                    throw new InvalidFieldsException(List.of("telephone"));
483	                }
484	            });
485	    }
486	
487	    /**
488	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
489	     * and a domain containing at least one dot, none of the parts holding whitespace or a
490	     * second {@code @}.
491	     */
492	    private static final java.util.regex.Pattern EMAIL_PATTERN =
493	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
494	
495	    /**
496	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
497	     * accepted and returned unchanged. When present it must be a syntactically valid address;
498	     * the value is stored and returned lower-cased. When present but invalid an
499	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
500	     * response naming the {@code email} field.
501	     *
502	     * @param email the submitted email value, or {@code null} when omitted
503	     * @return the lower-cased email, or {@code null} when none was supplied
504	     */
505	    private String normalizeEmail(String email) {
506	        if (email == null) {
507	            return null;
508	        }
509	        String trimmed = email.trim();
510	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
511	            throw new InvalidFieldsException(List.of("email"));
512	        }
513	        return canonicalEmail(trimmed);
514	    }
515	
516	    /**
517	     * Reduces an email to the canonical form used both to store it and to compare it against
518	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
519	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
520	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
521	     * value read back off an existing owner without risk of rejecting it. This is the single
522	     * definition of email identity: two emails denote the same address exactly when they
523	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
524	     * an email already on an existing owner can be compared for equality after both pass through
525	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
526	     *
527	     * @param email the email to canonicalize, or {@code null} when none was supplied
528	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
529	     */
530	    private String canonicalEmail(String email) {
531	        if (email == null) {
532	            return null;
533	        }
534	        return email.trim().toLowerCase(java.util.Locale.ROOT);
535	    }
536	
537	    /**
538	     * Rejects a new owner whose derived identity key is already used by any existing owner. All
539	     * duplicate detection is consolidated into this single key (see
540	     * {@link Owner#identityKey(String, String, String)}): the normalized E.164 telephone, the
541	     * canonical (trimmed, lower-cased) email and the household identifier the owner would receive,
542	     * joined by {@code '|'}. The submitted telephone and email have already been normalized in
543	     * place, and the household identifier is the value {@link #assignHousehold} would later store
544	     * (see {@link #prospectiveHouseholdId(OwnerFieldsDto)}). An owner is a duplicate only when its
545	     * whole key equals an existing owner's, so a difference in any part — for example two members
546	     * of one household with different telephones — yields distinct keys and is allowed. When a
547	     * match is found a {@link DuplicateIdentityException} is thrown, which the exception advice
548	     * renders as a 409 Conflict response.
549	     *
550	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
551	     */
552	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
553	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
554	            canonicalEmail(ownerFieldsDto.getEmail()), prospectiveHouseholdId(ownerFieldsDto));
555	        boolean taken = this.clinicService.findAllOwners().stream()
556	            .anyMatch(existing -> identityKey.equals(Owner.identityKey(existing.getTelephone(),
557	                canonicalEmail(existing.getEmail()), existing.getHouseholdId())));
558	        if (taken) {
559	            throw new DuplicateIdentityException(identityKey);
560	        }
561	    }
562	
563	    /**
564	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
565	     * set to {@code true}. The identifier is the one the owner would receive
566	     * ({@link #prospectiveHouseholdId(OwnerFieldsDto)}), derived deterministically from its
567	     * household identity so every owner in the same household resolves to the same stable value.
568	     * The new owner receives that value, and any existing household mates that do not yet carry it
569	     * are updated so the whole household shares one identifier. When the request did not opt in the
570	     * owner is left without a household identifier.
571	     *
572	     * @param owner the newly created owner, mutated in place with its household identifier
573	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
574	     */
575	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
576	        String householdId = prospectiveHouseholdId(ownerFieldsDto);
577	        if (householdId == null) {
578	            return;
579	        }
580	        owner.setHouseholdId(householdId);
581	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
582	            if (!householdId.equals(mate.getHouseholdId())) {
583	                mate.setHouseholdId(householdId);
584	                this.clinicService.saveOwner(mate);
585	            }
586	        }
587	    }
588	
589	    /**
590	     * Derives the {@code householdId} a newly submitted owner would receive, without needing the
591	     * owner to have been mapped or persisted yet. An owner shares a household only when the request
592	     * opts in via {@code sharesHousehold}; when it does, the identifier is derived deterministically
593	     * from the owner's household identity (its {@code lastName} and {@code address}, see
594	     * {@link #householdIdFor(String, String)}), so it matches the value {@link #assignHousehold} will
595	     * later store and every household mate resolves to the same identifier. When the request did not
596	     * opt in the owner belongs to no shared household and {@code null} is returned.
597	     *
598	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
599	     * @return the household identifier the owner would receive, or {@code null} when it shares none
600	     */
601	    private String prospectiveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
602	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
603	            return null;
604	        }
605	        return householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
606	    }
607	
608	    /**
609	     * Derives the stable {@code householdId} shared by every owner in the household identified by
610	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
611	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
612	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
613	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
614	     *
615	     * @param lastName the household's last name
616	     * @param address the household's address
617	     * @return the deterministic household identifier
618	     */
619	    private String householdIdFor(String lastName, String address) {
620	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
621	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
622	        try {
623	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
624	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
625	            StringBuilder sb = new StringBuilder();
626	            for (int i = 0; i < 8; i++) {
627	                sb.append(String.format("%02X", digest[i]));
628	            }
629	            return "HH-" + sb;
630	        }
631	        catch (java.security.NoSuchAlgorithmException e) {
632	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
633	        }
634	    }
635	
636	    /**
637	     * Counts the owners that belong to the household identified by the given {@code householdId},
638	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
639	     * of owners, so after a create it reflects the household's size including the newly persisted
640	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
641	     * household and yields {@code 0}.
642	     *
643	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
644	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
645	     */
646	    private int countHouseholdMembers(String householdId) {
647	        if (householdId == null) {
648	            return 0;
649	        }
650	        return (int) this.clinicService.findAllOwners().stream()
651	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
652	            .count();
653	    }
654	
655	    /**
656	     * Finds every existing owner that shares a household with the given {@code lastName} and
657	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
658	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
659	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
660	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
661	     * every rule that reasons about households.
662	     *
663	     * @param lastName the last name to match on
664	     * @param address the address to match on
665	     * @return the owners sharing the household, in encounter order (possibly empty)
666	     */
667	    private List<Owner> findHouseholdMates(String lastName, String address) {
668	        String normalizedLastName = collapseWhitespace(lastName);
669	        String normalizedAddress = normalizeAddress(address);
670	        return this.clinicService.findAllOwners().stream()
671	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
672	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
673	            .toList();
674	    }
675	
676	    /**
677	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
678	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
679	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
680	     *
681	     * @param value the value to collapse, or {@code null}
682	     * @return the whitespace-collapsed value, never {@code null}
683	     */
684	    private String collapseWhitespace(String value) {
685	        if (value == null) {
686	            return "";
687	        }
688	        return value.trim().replaceAll("\\s+", " ");
689	    }
690	
691	    /**
692	     * Common street-type abbreviations expanded during address normalization, keyed by their
693	     * upper-cased token.
694	     */
695	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
696	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
697	
698	    /**
699	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
700	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
701	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
702	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
703	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
704	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
705	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
706	     * everywhere an address is stored or compared.
707	     *
708	     * @param address the submitted address value, or {@code null}
709	     * @return the normalized address, never {@code null}
710	     */
711	    private String normalizeAddress(String address) {
712	        if (address == null) {
713	            return "";
714	        }
715	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
716	        if (collapsed.isEmpty()) {
717	            return "";
718	        }
719	        String[] tokens = collapsed.split(" ");
720	        StringBuilder sb = new StringBuilder(collapsed.length());
721	        for (int i = 0; i < tokens.length; i++) {
722	            if (i > 0) {
723	                sb.append(' ');
724	            }
725	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
726	        }
727	        return sb.toString();
728	    }
729	}
